/// Returns the transport-OK not-found envelope the Go fake host returns
/// when the shared stub has no response for a call. The IDL method table
/// below keeps the message taxonomy in step, and both test suites assert
/// the exact bytes so an undefined stub cannot diverge between hosts.
pub fn absent_response(service: &str, method_id: u32) -> Vec<u8> {
    let known_service = METHODS.iter().any(|(name, _, _)| *name == service);
    let message = if !known_service {
        format!("unknown service {:?}", service)
    } else if let Some((_, _, method)) = METHODS
        .iter()
        .find(|(name, id, _)| *name == service && *id == method_id)
    {
        format!("no stub response for {service}.{method}")
    } else {
        format!("unknown method {method_id} for service {service:?}")
    };
    format!("{{\"code\":\"not-found\",\"message\":{}}}", json_string(&message))
        .into_bytes()
}

/// Escapes one string exactly as Go's encoding/json escapes a string.
fn json_string(value: &str) -> String {
    let mut out = String::with_capacity(value.len() + 2);
    out.push('"');
    for c in value.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '<' => out.push_str("\\u003c"),
            '>' => out.push_str("\\u003e"),
            '&' => out.push_str("\\u0026"),
            '\u{2028}' => out.push_str("\\u2028"),
            '\u{2029}' => out.push_str("\\u2029"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
    out
}
